const inputItem = $input.item(0).json;
let geminiRaw = inputItem.content || inputItem.text || '';
let parsed = null;

try {
  const jsonMatch = geminiRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch (e) {
  parsed = null;
}

const original = $('Google Sheets: Tra Cứu Lịch Sử Sức Khỏe').first()?.json || {
  employeeName: 'Nguyễn Văn A',
  employeeEmail: 'nguyen.vana@company.com',
  department: 'Phòng Kỹ thuật & AI',
  sentimentScore: -0.6
};

let actionType = parsed?.actionType || 'COFFEE_VOUCHER';
let packageTitle = parsed?.packageTitle || 'Gói Phục Hồi Năng Lượng: E-Voucher Highlands & Half-day Rest';
let actionCode = 'ACT_GEMINI_' + Date.now();

if (!parsed) {
  if (Number(original.sentimentScore || -0.5) <= -0.7) {
    actionType = 'COUNSELING_CHAT';
    packageTitle = 'Buổi Trò Chuyện Tâm Lý 1-on-1 Bảo Mật với HR Lead';
  } else if (original.department && original.department.includes('Kỹ thuật')) {
    actionType = 'WORKLOAD_RELIEF';
    packageTitle = 'Điều Phối Giảm Tải Sprint & Cẩm Nang Mindfulness Chống Burnout';
  }
}

return {
  ...original,
  actionCode,
  actionType,
  packageTitle,
  executedAt: new Date().toISOString()
};
